<article class="portfolio-simple">
    <header class="simple-head"><div><p class="eyebrow">Simple Portfolio</p><h1>{{ $portfolio->full_name }}</h1><p>{{ $portfolio->about_me }}</p><div class="link-list">@if ($portfolio->email)<a class="portfolio-link" href="mailto:{{ $portfolio->email }}">{{ $portfolio->email }}</a>@endif @if ($portfolio->contact_number)<a class="portfolio-link" href="tel:{{ $portfolio->contact_number }}">{{ $portfolio->contact_number }}</a>@endif @if ($portfolio->address)<span class="item-period">{{ $portfolio->address }}</span>@endif</div></div><div class="portfolio-avatar">@if ($avatarUrl)<img src="{{ $avatarUrl }}" alt="{{ $portfolio->full_name }}">@else{{ $initials }}@endif</div></header>
    @if ($portfolio->projects)<section class="portfolio-section"><h2>Selected projects</h2><div class="item-list">@foreach ($portfolio->projects as $item)<div class="portfolio-item"><div><h3>{{ $item['title'] ?? '' }}</h3><p>{{ $item['description'] ?? '' }}</p>@if (!empty($item['url']))<a class="portfolio-link" href="{{ $item['url'] }}" target="_blank" rel="noopener noreferrer">View project ↗</a>@endif</div></div>@endforeach</div></section>@endif
    @if ($portfolio->experience)<section class="portfolio-section"><h2>Experience</h2><div class="item-list">@foreach ($portfolio->experience as $item)<div class="portfolio-item"><div><h3>{{ $item['role'] ?? '' }} · {{ $item['company'] ?? '' }}</h3><p>{{ $item['description'] ?? '' }}</p></div><span class="item-period">{{ $item['period'] ?? '' }}</span></div>@endforeach</div></section>@endif
    @if ($portfolio->education)<section class="portfolio-section"><h2>Education</h2><div class="item-list">@foreach ($portfolio->education as $item)<div class="portfolio-item"><div><h3>{{ $item['degree'] ?? '' }}</h3><p>{{ $item['institution'] ?? '' }}</p></div><span class="item-period">{{ $item['year'] ?? '' }}</span></div>@endforeach</div></section>@endif
    @if ($portfolio->skills)<section class="portfolio-section"><h2>Skills</h2><div class="skill-list">@foreach ($portfolio->skills as $skill)<span class="skill-pill">{{ $skill }}</span>@endforeach</div></section>@endif
    @if ($portfolio->social_links)<section class="portfolio-section"><h2>Elsewhere</h2><div class="link-list">@foreach ($portfolio->social_links as $link)<a class="portfolio-link" href="{{ $link['url'] }}" target="_blank" rel="noopener noreferrer">{{ $link['label'] ?: $link['url'] }} ↗</a>@endforeach</div></section>@endif
</article>